/**
 * Golden tables: the compiler's output against REFERENCE renderings stored as fixtures.
 *
 * - tests/golden/icu4c.json — ICU4C 78 MessageFormat, generated by
 *   scripts/icu-golden/gen-icu4c.mjs from scripts/icu-golden/cases.mjs. Rows marked
 *   `error` are templates ICU4C rejects: core renders the key and reports `syntax`.
 *   Rows marked `coerced` pass a numeric STRING count; ICU4C rendered them from
 *   Number(string), which is what core does (owner decision 27.10.2026). Rows marked
 *   `plain` have a plain `{x}` holding a number: core prints String(value) there, never
 *   Intl (owner decision R3-17, 28.10.2026), so ICU4C rendered them with String(value)
 *   as that argument and formatted everything else (`#`) itself.
 * - tests/golden/formatjs.json — intl-messageformat 10.7.16 over the lot-0 S3
 *   differential subset that lies inside the 0.8 grammar
 *   (scripts/icu-golden/gen-formatjs.mjs).
 *
 * Neither fixture is ever regenerated by the test run.
 */
import { describe, expect, it } from "vitest";
import icu4c from "../golden/icu4c.json";
import formatjs from "../golden/formatjs.json";
import { fmt, revive, sink } from "../helpers";

interface Row {
  pattern: string;
  locale: string;
  args: Record<string, unknown>;
  expected?: string;
  error?: string;
  /** A numeric-string count, rendered by ICU4C from Number(string) (owner, 27.10.2026). */
  coerced?: boolean;
  /** A plain `{x}` holds a number, rendered by ICU4C from String(value) (R3-17). */
  plain?: boolean;
}

describe("ICU4C golden table", () => {
  const rows = icu4c.rows as Row[];

  it("covers the grammar: plural, selectordinal, select, =N, offset, #, quoting, errors", () => {
    expect(rows.length).toBeGreaterThan(250);
    for (const needle of ["selectordinal", "select,", "offset:", "=0", "'#'", "''"]) {
      expect(rows.some((r) => r.pattern.includes(needle))).toBe(true);
    }
    expect(rows.filter((r) => r.error).length).toBeGreaterThanOrEqual(10);
  });

  it("has numeric-string count rows, and every one of them passes a string", () => {
    const coerced = rows.filter((r) => r.coerced);
    expect(coerced.length).toBeGreaterThanOrEqual(20);
    for (const r of coerced) expect(typeof r.args.n).toBe("string");
  });

  it("has plain-number rows, and each prints the number as String(value) (R3-17)", () => {
    const plain = rows.filter((r) => r.plain);
    expect(plain.length).toBeGreaterThanOrEqual(40);
    const x = plain.filter((r) => r.pattern === "{x}");
    expect(x.length).toBeGreaterThanOrEqual(20);
    for (const r of x) expect(r.expected).toBe(String(r.args.x));
  });

  it.each(
    rows
      .filter((r) => !r.error)
      .map((r) => [r.locale, r.pattern, JSON.stringify(r.args), r] as const),
  )("[%s] %s %s", (_l, _p, _a, row) => {
    const env = sink();
    expect(fmt(row.pattern, revive(row.args), row.locale, env)).toBe(row.expected);
    expect(env.errors).toEqual([]);
  });

  it.each(rows.filter((r) => r.error).map((r) => [r.pattern, r.error!, r] as const))(
    "rejects %s (ICU4C: %s) — renders the key, reports syntax",
    (_p, _e, row) => {
      const env = sink();
      expect(fmt(row.pattern, revive(row.args), row.locale, env, "the.key")).toBe("the.key");
      expect(env.errors.map((e) => e.code)).toEqual(["syntax"]);
      expect(env.errors[0]).toMatchObject({ key: "the.key", locale: row.locale });
    },
  );
});

describe("formatjs differential subset (lot-0 S3, supported grammar)", () => {
  const rows = formatjs.rows as Row[];

  it("has every locale of the spike", () => {
    expect(new Set(rows.map((r) => r.locale))).toEqual(new Set(["en", "de", "uk", "ar-EG", "ja"]));
  });

  it.each(rows.map((r) => [r.locale, r.pattern, JSON.stringify(r.args), r] as const))(
    "[%s] %s %s",
    (_l, _p, _a, row) => {
      expect(fmt(row.pattern, revive(row.args), row.locale)).toBe(row.expected);
    },
  );
});
